# ============================================================================
# Embedded channel data (zlib + base64, do not edit)
# ============================================================================

_CHANNELS_B64 = """"""


def _load_channels():
    raw = zlib.decompress(base64.b64decode(_CHANNELS_B64))
    return json.loads(raw)


# ============================================================================
# Config
# ============================================================================

MAX_HEIGHT = 1080
CHUNK_DURATION = 240
SKIP_START = 120
SKIP_END = 120
MIN_VIDEO_DURATION = 60

MANIFEST_FIELDS = [
    "channel_id", "channel_name", "video_id", "filename",
    "title", "upload_date", "duration", "chunk_start", "chunk_end",
    "width", "height", "max_available_height", "codec", "fps",
    "license", "yt_category", "tags", "description",
    "download_timestamp", "file_size", "status", "error",
]

API_DELAY = 1.0
DOWNLOAD_DELAY = 15.0
_last_api = 0.0
_last_dl = 0.0


# ============================================================================
# yt-dlp wrapper
# ============================================================================

def run_ytdlp(args, timeout=60, is_download=False):
    global _last_api, _last_dl

    now = time.time()
    if is_download:
        wait = DOWNLOAD_DELAY - (now - _last_dl)
        if wait > 0:
            time.sleep(wait)
        _last_dl = time.time()
    else:
        wait = API_DELAY - (now - _last_api)
        if wait > 0:
            time.sleep(wait)
        _last_api = time.time()

    cmd = ["yt-dlp"]

    # Write cookies to temp file
    tmp = tempfile.NamedTemporaryFile(suffix=".txt", prefix="ytdlp_c_", delete=False, mode="w")
    tmp.write(COOKIES_TEXT)
    tmp.close()
    cmd += ["--cookies", tmp.name]

    env = os.environ.copy()
    deno_bin = Path.home() / ".deno" / "bin"
    if deno_bin.exists():
        env["PATH"] = f"{deno_bin}:{env.get('PATH', '')}"
    cmd += ["--remote-components", "ejs:github"]
    cmd += args

    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, env=env)
    finally:
        Path(tmp.name).unlink(missing_ok=True)


def list_channel_videos(channel_id, max_videos):
    result = run_ytdlp([
        "--flat-playlist",
        "--print", "%(id)s\t%(duration)s\t%(title)s",
        "--playlist-end", str(max_videos),
        f"https://www.youtube.com/channel/{channel_id}/videos",
    ], timeout=30)
    if result.returncode != 0:
        return []
    videos = []
    for line in result.stdout.splitlines():
        parts = line.strip().split("\t", 2)
        if len(parts) >= 2 and parts[0] != "NA":
            try:
                dur = float(parts[1]) if parts[1] not in ("NA", "None", "") else 0
                title = parts[2] if len(parts) > 2 else ""
                videos.append({"id": parts[0], "duration": dur, "title": title})
            except (ValueError, IndexError):
                continue
    return videos


def compute_chunk_range(duration):
    if duration < MIN_VIDEO_DURATION:
        return None
    if duration < CHUNK_DURATION:
        return (0, int(duration))
    usable_start = min(SKIP_START, duration * 0.1)
    usable_end = max(duration - SKIP_END, duration * 0.9)
    usable = usable_end - usable_start
    if usable < CHUNK_DURATION:
        center = duration / 2
        start = max(0, int(center - CHUNK_DURATION / 2))
        return (start, start + CHUNK_DURATION)
    center = usable_start + usable / 2
    start = int(center - CHUNK_DURATION / 2)
    return (start, start + CHUNK_DURATION)


def append_manifest(manifest_path, row):
    write_header = not manifest_path.exists()
    with open(manifest_path, "a", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=MANIFEST_FIELDS)
        if write_header:
            writer.writeheader()
        writer.writerow(row)


def download_video(video_id, video_duration, channel_id, channel_name,
                   output_dir, manifest_path, downloaded_ids):
    if video_id in downloaded_ids:
        return False

    chunk = compute_chunk_range(video_duration)
    if chunk is None:
        append_manifest(manifest_path, {
            **{k: "" for k in MANIFEST_FIELDS},
            "channel_id": channel_id, "channel_name": channel_name,
            "video_id": video_id, "status": "skipped",
            "error": f"too short ({video_duration:.0f}s)",
            "download_timestamp": datetime.now(timezone.utc).isoformat(),
        })
        downloaded_ids.add(video_id)
        return False

    start, end = chunk
    base_name = f"{channel_id}_{video_id}_{start}-{end}"
    output_template = str(output_dir / f"{base_name}.%(ext)s")

    existing = [f for f in output_dir.glob(f"{base_name}.*")
                if f.suffix not in (".json", ".part")]
    if existing:
        downloaded_ids.add(video_id)
        return False

    result = run_ytdlp([
        "-f", f"bestvideo[height<={MAX_HEIGHT}]+bestaudio/best[height<={MAX_HEIGHT}]",
        "--download-sections", f"*{start}-{end}",
        "--write-info-json",
        "-o", output_template,
        "--no-playlist",
        f"https://www.youtube.com/watch?v={video_id}",
    ], timeout=300, is_download=True)

    downloaded = [f for f in output_dir.glob(f"{base_name}.*")
                  if f.suffix not in (".json", ".part")]
    filepath = downloaded[0] if downloaded else None

    if result.returncode != 0 or not filepath:
        error_msg = result.stderr[-300:].strip() if result.stderr else "unknown error"
        append_manifest(manifest_path, {
            **{k: "" for k in MANIFEST_FIELDS},
            "channel_id": channel_id, "channel_name": channel_name,
            "video_id": video_id, "status": "failed",
            "error": error_msg[:500],
            "download_timestamp": datetime.now(timezone.utc).isoformat(),
        })
        downloaded_ids.add(video_id)
        return False

    info = {}
    info_json = list(output_dir.glob(f"{base_name}.info.json"))
    if info_json:
        try:
            with open(info_json[0]) as f:
                info = json.load(f)
            info_json[0].unlink()
        except (json.JSONDecodeError, OSError):
            pass

    max_avail = max((fmt.get("height") or 0) for fmt in info.get("formats", [{}]))
    file_size = filepath.stat().st_size

    downloaded_ids.add(video_id)
    append_manifest(manifest_path, {
        "channel_id": channel_id, "channel_name": channel_name,
        "video_id": video_id, "filename": filepath.name,
        "title": str(info.get("title", ""))[:200],
        "upload_date": info.get("upload_date", ""),
        "duration": info.get("duration", video_duration),
        "chunk_start": start, "chunk_end": end,
        "width": info.get("width", 0), "height": info.get("height", 0),
        "max_available_height": max_avail,
        "codec": info.get("vcodec", ""), "fps": info.get("fps", 0),
        "license": info.get("license", "Standard YouTube License"),
        "yt_category": (info.get("categories", []) or [""])[0],
        "tags": "|".join(info.get("tags") or [])[:500],
        "description": str(info.get("description", ""))[:500],
        "download_timestamp": datetime.now(timezone.utc).isoformat(),
        "file_size": file_size, "status": "downloaded", "error": "",
    })
    return True


# ============================================================================
# Main
# ============================================================================

@click.command(help="Standalone YouTube chunk downloader")
@click.option("--output-dir", default="youtube_downloads")
@click.option("--api-delay", type=float, default=1.0)
@click.option("--download-delay", type=float, default=15.0)
@click.option("--videos-per-channel", type=int, default=20)
@click.option("--total-limit", type=int, default=0)
@click.option("--category", default=None, help="Single category")
@click.option("--shards", type=int, default=1, help="Total number of machines/shards")
@click.option("--shard-id", type=int, default=0, help="This machine's shard ID, 0-indexed")
@click.option("--dry-run", is_flag=True)
def main(output_dir, api_delay, download_delay, videos_per_channel, total_limit,
         category, shards, shard_id, dry_run):
    global API_DELAY, DOWNLOAD_DELAY
    API_DELAY = api_delay
    DOWNLOAD_DELAY = download_delay

    all_channels = _load_channels()
    output_base = Path(output_dir)
    categories = [category] if category else sorted(all_channels.keys())

    # Shard channels within each category — each machine gets every Nth channel
    if shards > 1:
        for cat in list(all_channels.keys()):
            all_channels[cat] = [
                ch for i, ch in enumerate(all_channels[cat])
                if i % shards == shard_id
            ]
        shard_label = f" [shard {shard_id}/{shards}]"
    else:
        shard_label = ""

    # Load existing downloads for resume
    cat_downloaded = {}
    for cat in categories:
        out = output_base / cat
        out.mkdir(parents=True, exist_ok=True)
        downloaded = set()
        manifest = out / "manifest.csv"
        if manifest.exists():
            with open(manifest) as f:
                for row in csv.DictReader(f):
                    vid = row.get("video_id", "")
                    if vid:
                        downloaded.add(vid)
        cat_downloaded[cat] = downloaded

    if dry_run:
        for cat in categories:
            print(f"{cat}{shard_label}: {len(all_channels.get(cat, []))} channels, "
                  f"{len(cat_downloaded.get(cat, set()))} downloaded")
        total_ch = sum(len(all_channels.get(cat, [])) for cat in categories)
        print(f"\nTotal: {total_ch} channels{shard_label}")
        return

    channel_idx = {cat: 0 for cat in categories}
    video_cache = {}
    total_done = 0
    total_failed = 0
    total_bytes = 0
    start_time = time.time()

    pbar = tqdm(desc="Downloading", unit="vid", file=sys.stderr,
                bar_format="{desc}: {n_fmt} vids | {postfix} | {elapsed}")

    try:
        while True:
            made_progress = False
            for cat in categories:
                if total_limit and total_done >= total_limit:
                    break

                channels = all_channels.get(cat, [])
                downloaded = cat_downloaded[cat]
                out_dir = output_base / cat
                manifest = out_dir / "manifest.csv"

                attempts = 0
                video = None
                while attempts < len(channels):
                    idx = channel_idx[cat] % len(channels)
                    cid, cname = channels[idx]
                    channel_idx[cat] = idx + 1
                    if cid not in video_cache:
                        vids = list_channel_videos(cid, videos_per_channel)
                        video_cache[cid] = [
                            v for v in vids
                            if v["duration"] > MIN_VIDEO_DURATION
                            and v["id"] not in downloaded
                        ]
                    if video_cache[cid]:
                        video = video_cache[cid].pop(0)
                        break
                    attempts += 1

                if video is None:
                    continue

                made_progress = True
                ok = download_video(
                    video["id"], video["duration"], cid, cname,
                    out_dir, manifest, downloaded,
                )
                if ok:
                    total_done += 1
                    fs = [f for f in out_dir.glob(f"*{video['id']}*")
                          if f.suffix not in (".json", ".part")]
                    if fs:
                        total_bytes += fs[0].stat().st_size
                else:
                    total_failed += 1

                elapsed = time.time() - start_time
                speed = (total_bytes / 1e6) / elapsed if elapsed > 0 else 0
                pbar.n = total_done
                pbar.set_postfix_str(
                    f"{total_bytes / 1e9:.1f}GB | {speed:.1f}MB/s | {total_failed} failed"
                )
                pbar.refresh()

            if not made_progress:
                tqdm.write("All categories exhausted.")
                break
            if total_limit and total_done >= total_limit:
                break

    except KeyboardInterrupt:
        print("\nInterrupted — progress saved.")

    pbar.close()
    print(f"\nDone: {total_done} downloaded, {total_failed} failed, {total_bytes / 1e9:.1f}GB")


if __name__ == "__main__":
    main()
